def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, 90.0))
        return float(min(budget, 28.0))

    prev_bids = []
    cindy_bid = None
    cindy_budget = None
    for oid, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if oid == 'Cindy':
            cindy_budget = opp.get('budget', 0.0)
            if bid is not None:
                cindy_bid = float(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure_bid = cindy_bid if cindy_bid is not None else highest_prev

    competitors = 1
    for opp in alive_opponents:
        req = opp.get('water_requirement', WATER_REQ)
        if supply >= req:
            competitors += 1

    base = 0.0
    if supply >= 24:
        base = 22.0
    elif supply >= 21:
        base = 34.0
    elif supply >= 18:
        base = 52.0
    else:
        base = 74.0

    if competitors >= 2 and supply < 2 * WATER_REQ:
        base = max(base, pressure_bid + 3.0)
    elif pressure_bid > 0:
        base = max(base, pressure_bid * 0.72)

    if hp <= 2 or no_water >= 2:
        base = max(base, pressure_bid + 6.0, 95.0)
    elif hp <= 4 or no_water >= 1:
        base = max(base, pressure_bid + 2.0, 78.0)

    if cindy_budget is not None and cindy_budget < 120:
        base = max(40.0, min(base, cindy_budget + 1.0))

    if day >= 8:
        base += 8.0

    safe_cap = budget
    if day < 8:
        reserve = max(0.0, (10 - day) * 18.0)
        safe_cap = max(0.0, budget - reserve)
        if hp <= 3 or no_water >= 1:
            safe_cap = budget

    bid = min(budget, max(0.0, min(base, safe_cap if safe_cap > 0 else budget)))

    if bid < 1.0 and budget > 0:
        bid = min(budget, 1.0)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp is None:
            continue
        if bool(opp.get('alive', False)):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday's bids (only previous_trace)
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate likely clearing price pressure from yesterday
    if prev_bids:
        highest_prev = max(prev_bids)
        # If someone bid extremely high yesterday, we must at least contest.
        if highest_prev >= DAILY_SALARY * 0.9:
            base = DAILY_SALARY * (0.65 if hp > 3.0 else 0.95)
        elif highest_prev >= DAILY_SALARY * 0.7:
            base = DAILY_SALARY * (0.55 if hp > 3.0 else 0.85)
        else:
            base = max(DAILY_SALARY * 0.45, highest_prev + 3.0)
    else:
        base = DAILY_SALARY * (0.55 if hp > 3.0 else 0.85)

    # Supply-aware adjustment: with higher supply, we can bid less to conserve budget.
    # supply is between 15 and 25; normalize to [0,1]
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        s_norm = 0.5
    else:
        s_norm = (supply - float(MIN_SUPPLY)) / denom
    s_norm = 0.0 if s_norm < 0.0 else (1.0 if s_norm > 1.0 else s_norm)

    # When supply is high, bid slightly lower; when low, bid slightly higher.
    supply_factor = 1.0 + (0.12 * (0.5 - s_norm))  # ~+6% at low, ~-6% at high
    target = base * supply_factor

    # Hard budget cap and non-negative
    target = max(0.0, min(target, budget))

    # If our hp is critical, increase bid to secure water.
    if hp <= 2.0:
        target = min(budget, max(target, DAILY_SALARY * 0.9))
    elif hp <= 4.0:
        target = min(budget, max(target, DAILY_SALARY * 0.7))

    # Small step to avoid ties: add tiny epsilon if possible.
    eps = 0.01
    if budget - target >= eps:
        target = target + eps

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Estimate yesterday's max bid among alive opponents
    max_prev_bid = 0
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                max_prev_bid = max(max_prev_bid, float(prev['bid']))

    # Decide bid based on urgency
    if hp <= 3 or no_water_days >= 2:
        # Need water urgently: outbid yesterday's max by 10-15%
        target = max(DAILY_SALARY * 0.9, max_prev_bid * 1.1)
        return min(budget, target)
    elif hp <= 5:
        # Moderate need: bid somewhat above average expectation
        target = max(DAILY_SALARY * 0.6, max_prev_bid * 0.95)
        return min(budget, target)
    else:
        # Healthy: save money, bid low but not zero
        base = DAILY_SALARY * 0.4
        # If supply is low, slightly increase
        if supply < (MIN_SUPPLY + MAX_SUPPLY) / 2:
            base *= 1.2
        return min(budget, base)
